/*
 * A100110  Write n in decimal and replace each digit d with prime(d+1), add
 *          overflow to the next position left.
 * https://oeis.org/A100110
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) = form the decimal number obtained by writing n in base‑10,
 *            replacing each digit d by the (d+1)‑th prime, and then adding
 *            any carry generated by the replacement to the next more
 *            significant digit
 * Range:     u8 n <= 88, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    static const seq_t prime[10] = {
        (seq_t)2, (seq_t)3, (seq_t)5, (seq_t)7,
        (seq_t)11, (seq_t)13, (seq_t)17, (seq_t)19,
        (seq_t)23, (seq_t)29
    };
    idx_t temp = n;
    seq_t carry   = 0;
    seq_t result  = 0;
    seq_t pow10   = 1;
    int  started  = 0;        /* at least one digit has been processed */

    while (temp > 0 || started == 0) {
        int d;
        if (temp > 0) {
            d = temp % 10;
            temp /= 10;
        } else {
            d = 0;            /* treat missing higher digits as 0 */
        }
        seq_t p   = prime[d];
        seq_t s   = p + carry;
        seq_t digit = s % 10;
        carry = s / 10;

        result += digit * pow10;
        pow10  *= 10;
        started = 1;
    }

    while (carry > 0) {
        seq_t digit = carry % 10;
        result += digit * pow10;
        pow10  *= 10;
        carry  /= 10;
    }

    return result;
}
